
declare @tabprod table (produto varchar(12))

select A.*,B.FILIAL,B.ESTOQUE,PP.PRECO1,C.DESC_PRODUTO
from @tabprod a
inner join estoque_produtos b on b.produto = a.produto and b.filial='LOJA VIRTUAL'
INNER JOIN PRODUTOS C ON C.PRODUTO =A.PRODUTO
INNER JOIN PRODUTOS_PRECOS PP ON PP.PRODUTO =A.PRODUTO AND PP.CODIGO_TAB_PRECO='73'
WHERE B.ESTOQUE>0